import type {SidebarsConfig} from '@docusaurus/plugin-content-docs';

/**
 * One single hierarchical documentation tree, rooted at `Systems`.
 *
 * Everything below `docs/systems/` is autogenerated from the filesystem so that
 * dropping an `.mdx` file into the right arc42 folder is enough to make it show
 * up in the navigation:
 *
 *   docs/systems/<system>/                       -> a system category
 *   docs/systems/<system>/NN-<arc42-section>.mdx -> an arc42 section without children
 *   docs/systems/<system>/NN-<arc42-section>/    -> an arc42 section with custom child pages
 *   docs/systems/<system>/components/<component> -> a component category
 *
 * The `NN-` prefixes only drive ordering; Docusaurus strips them from the URL
 * and from the sidebar label, so no `overview/` or `arc42/` path segments and
 * no intermediate navigation nodes are ever created.
 *
 * `index.mdx` inside a folder is used automatically as that category's landing
 * page, which is why systems and components have a useful landing page without
 * an extra `Overview` sidebar item.
 */
const sidebars: SidebarsConfig = {
  docsSidebar: [
    {
      type: 'category',
      label: 'Systems',
      collapsible: false,
      collapsed: false,
      link: {type: 'doc', id: 'systems-index'},
      items: [{type: 'autogenerated', dirName: 'systems'}],
    },
  ],
};

export default sidebars;
